// Récupérer les données de chaque nœud
let volumeData = [], mttrData = {}, patternsData = [];

try { volumeData   = $('Stats Volume').all().map(i => i.json); } catch(e) {}
try { mttrData     = $('Stats MTTR+Faux Positifs').first().json; } catch(e) {}
try { patternsData = $('Top 5 Patterns').all().map(i => i.json); } catch(e) {}

// Volume par état
const volume = { INFO: 0, WARNING: 0, ERROR: 0, ERROR_CASCADE: 0, CRITICAL: 0, RECOVERY: 0 };
for (const row of volumeData) {
  if (row.afd_state) volume[row.afd_state] = parseInt(row.count) || 0;
}

const totalLogs = Object.values(volume).reduce((a, b) => a + b, 0);

// Top patterns
const topPatterns = patternsData.length > 0
  ? patternsData
      .slice(0, 5)
      .map((p, i) => `${i + 1}. ${(p.message || 'N/A').substring(0, 60)} (${p.occurrences || 0}x)`)
      .join('\n')
  : 'Aucun pattern critique détecté';

const statsJson = JSON.stringify({
  total_logs: totalLogs,
  volume,
  mttr_minutes: mttrData.mttr_minutes || 'N/A',
  false_positive_rate: mttrData.false_positive_rate || 0,
  top_patterns: patternsData.slice(0, 3).map(p => p.message || '')
});

const today = new Date().toLocaleDateString('fr-FR', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

return [{
  json: {
    volume,
    totalLogs,
    mttr_minutes:        mttrData.mttr_minutes || 'N/A',
    false_positive_rate: mttrData.false_positive_rate || 0,
    topPatterns,
    statsJson,
    today
  }
}];

const data = $input.first().json;
const today = new Date().toLocaleDateString('fr-FR', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

const rawStats = $('Merge des résultats').first().json;

const whatsappMarkdown = `📈 *Rapport LogSentinel — ${today}*

