// 3. Output both variables for downstream nodes
return [{
  json: {
    whatsappMarkdown,
    htmlEmail
  }
}];

const stats = $input.first().json;

let severity = 'HEALTHY';

if ((stats.volume?.CRITICAL || 0) > 0) {
  severity = 'CRITICAL';
} else if (
  (stats.volume?.WARNING || 0) > 5 ||
  (stats.volume?.ERROR || 0) > 10
) {
  severity = 'WARNING';
}

const metrics = {
  severity,
  total_logs: stats.totalLogs,

  volume: {
    INFO: stats.volume?.INFO || 0,
    WARNING: stats.volume?.WARNING || 0,
    ERROR: stats.volume?.ERROR || 0,
    ERROR_CASCADE: stats.volume?.ERROR_CASCADE || 0,
    CRITICAL: stats.volume?.CRITICAL || 0,
    RECOVERY: stats.volume?.RECOVERY || 0
  },

  mttr_minutes: stats.mttr_minutes || 'N/A',

  false_positive_rate: stats.false_positive_rate || 0,

  top_patterns: stats.topPatterns || 'Aucun pattern'
};

const userPrompt = `
Analyse les statistiques suivantes des dernières 24h:

${JSON.stringify(metrics, null, 2)}

Retourne UNIQUEMENT un JSON valide:
{
  "summary": "",
  "recommendation": "",
  "status": "HEALTHY|WARNING|CRITICAL"
}
`;

return [
  {
    json: {
      metrics,
      severity,
      today : stats.today,
      groq_body: {
        model: $env.GROQ_MODEL,
        messages: [
          {
            role: "system",
            content:
              "Tu es un ingénieur SRE senior spécialisé en observabilité."
          },
          {
            role: "user",
            content: userPrompt
          }
        ],
        temperature: 0.2
      }
    }
  }
];

const groq = $input.first().json;

// 1. Extract raw content
let content = groq.choices?.[0]?.message?.content || "";

// 2. Remove code blocks if present
content = content
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

// 3. Try to extract JSON object inside text
const jsonMatch = content.match(/\{[\s\S]*\}/);

let parsed;

try {
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error("No JSON found");
  }
} catch (e) {

  // fallback safe output
  parsed = {
    summary: "Le système est globalement stable.",
    recommendation: "Aucune action urgente requise.",
    status: "HEALTHY"
  };
}

// 4. Normalize fields (safety layer)
const result = {
  summary: parsed.summary || "Résumé indisponible.",
  recommendation: parsed.recommendation || "Aucune recommandation.",
  status: parsed.status || "HEALTHY"
};

return [
  {
    json: {
      ...groq,
      ...result
    }
  }
];
